	async tdocQueryBatchSaasImportProgress(params) {
		const result = await this.getDaemonClientFeature("tencentDocsQueryBatchSaasImportProgress")(params);
		const subTasks = Array.isArray(result?.sub_tasks) ? result.sub_tasks : [];
		const successCount = subTasks.filter((task) => task.status === SAAS_IMPORT_SUB_TASK_STATUS.SUCCESS).length;
		const failedCount = subTasks.filter((task) => task.status === SAAS_IMPORT_SUB_TASK_STATUS.FAILED).length;
		return {
			overall_status: typeof result?.status === "number" ? result.status : 0,
			total: subTasks.length,
			success_count: successCount,
			failed_count: failedCount,
			processing_count: Math.max(0, subTasks.length - successCount - failedCount),
			results: subTasks
		};
	}
