	async activateConversationMessageQueue(sessionId) {
		queueDiagLog.info("[adapter.activate] CALL RPC", {
			ts: (/* @__PURE__ */ new Date()).toISOString(),
			sessionId
		});
		const response = await this.client.sessions.activateConversationMessageQueue(sessionId);
		const item = response.item;
		const queue = response.queue ?? response;
		queueDiagLog.info("[adapter.activate] RPC returned", {
			sessionId,
			hasItem: !!item,
			poppedItemId: item?.id,
			poppedPreview: item?.previewText?.slice(0, 60),
			queueVersion: queue?.version,
			queueItemCount: Array.isArray(queue?.items) ? queue.items.length : "n/a"
		});
		if (item) {
			if (isCliInjectedTeammateQueueItem(item)) {
				queueDiagLog.info("[adapter.activate] popped item is CLI-injected teammate message — skip requestSendPrompt", {
					sessionId,
					itemId: item.id
				});
				return this._notifyQueueUpdate(queue);
			}
			const contentBlocks = item.contentBlocks;
			queueDiagLog.info("[adapter.activate] → silent queue dispatch", {
				sessionId,
				itemId: item.id,
				source: "queue-dispatch",
				contentBlockCount: Array.isArray(contentBlocks) ? contentBlocks.length : 0,
				hasContentBlocks: Array.isArray(contentBlocks) && contentBlocks.length > 0
			});
			this.markPromptConversationStarted(sessionId, Date.now());
			const sanitized = this._notifyQueueUpdate(queue);
			this.dispatchConversationQueueItemPrompt(sessionId, item);
			return sanitized;
		}
		queueDiagLog.info("[adapter.activate] no item to dispatch (queue empty or all drained)", { sessionId });
		return this._notifyQueueUpdate(queue);
	}
