	async installSkillFromUrl(params) {
		const requestedSkillName = params.skillName?.trim();
		if (!requestedSkillName) return {
			success: false,
			errorKey: "invalidSkillId",
			errorMessage: "Missing required skill identifier"
		};
		const downloadInput = params.downloadUrl?.trim();
		if (!downloadInput) return {
			success: false,
			errorKey: "invalidDownloadUrl",
			errorMessage: "Missing skill package path or URL"
		};
		try {
			const preparedResult = await this.prepareSkillPackageFromUrlIfNeeded({
				skillName: requestedSkillName,
				downloadUrl: downloadInput
			});
			if (!preparedResult.success || !preparedResult.downloadedFilePath) return {
				success: false,
				errorKey: preparedResult.errorKey || "installFromUrlFailed",
				errorMessage: preparedResult.errorMessage || "Failed to download skill package",
				warningKey: preparedResult.warningKey,
				warningMessage: preparedResult.warningMessage,
				skillName: preparedResult.skillName || requestedSkillName
			};
			const importResult = await this.importSkill({
				source: "userSettings",
				folderPath: preparedResult.downloadedFilePath,
				overwrite: params.overwrite,
				securityCheck: params.securityCheck ?? true,
				appKey: params.appKey
			});
			if (!importResult.success) {
				const errorKey = this.mapImportErrorToInstallErrorKey(importResult.error);
				return {
					success: false,
					errorKey,
					errorMessage: importResult.error || "Failed to import skill package",
					warningKey: preparedResult.warningKey,
					warningMessage: preparedResult.warningMessage,
					skillName: errorKey === "duplicateSkillName" ? importResult.skillName || preparedResult.skillName || requestedSkillName : void 0,
					preCheck: importResult.preCheck
				};
			}
			const installedSkillName = importResult.skillName || preparedResult.skillName || requestedSkillName;
			const activatedSkillId = this.normalizeSkillId(installedSkillName);
			this.invalidateSkillListCache();
			const installedSkillInfo = await this.findInstalledSkillInfoByName(installedSkillName);
			const installedFilePath = installedSkillInfo?.filePath;
			const result = {
				success: true,
				warningKey: preparedResult.warningKey,
				warningMessage: preparedResult.warningMessage,
				importedSkillIds: [activatedSkillId],
				activatedSkillId,
				skillName: installedSkillName,
				installedFilePath
			};
			this.reportTelemetry("skill_create", {
				id: result.skillName || params.skillName || "unknown",
				skillId: installedSkillInfo?.skillId,
				skillVersion: installedSkillInfo?.skillVersion,
				source: params.channelType === "marketplace" ? "marketplace" : "userSettings"
			});
			this.reportTelemetry("skill_action", {
				id: result.skillName || params.skillName || "unknown",
				skillId: installedSkillInfo?.skillId,
				skillVersion: installedSkillInfo?.skillVersion,
				action: "install",
				source: params.channelType === "marketplace" ? "marketplace" : "userSettings"
			});
			return result;
		} catch (error) {
			console.error("[WorkbuddyAdapter] installSkillFromUrl failed:", error);
			return {
				success: false,
				errorKey: "installFromUrlFailed",
				errorMessage: error instanceof Error ? error.message : "Unknown error"
			};
		}
	}
	async prepareSkillPackageFromUrlIfNeeded(params) {
		const remoteUrl = params.downloadUrl.trim();
		if (!/^https:\/\//i.test(remoteUrl)) return {
			success: true,
			skillName: params.skillName,
			downloadedFilePath: remoteUrl
		};
		try {
			const prepareFromUrl = this.daemonClient?.skillPrepareFromUrl;
			if (!prepareFromUrl) return {
				success: false,
				errorKey: "installFromUrlFailed",
				errorMessage: "Desktop host does not support skillPrepareFromUrl"
			};
			const data = await prepareFromUrl({
				skillName: params.skillName,
				downloadUrl: remoteUrl
			});
			return {
				success: data.success,
				errorKey: data.success ? void 0 : data.errorKey,
				errorMessage: data.success ? void 0 : data.errorMessage,
				warningKey: data.warningKey,
				warningMessage: data.warningMessage,
				skillName: data.skillName,
				downloadedFilePath: data.success ? data.downloadedFilePath : void 0
			};
		} catch (error) {
			console.error("[WorkbuddyAdapter] prepareSkillPackageFromUrlIfNeeded failed:", error);
			return {
				success: false,
				errorKey: "installFromUrlFailed",
				errorMessage: error instanceof Error ? error.message : "Unknown error"
			};
		}
	}
	normalizeSkillId(skillName) {
		return skillName.toLowerCase().replace(/\s+/g, "-").trim();
	}
	mapImportErrorToInstallErrorKey(error) {
		if (!error) return;
		if (error.includes("already exists")) return "duplicateSkillName";
		if (error.includes("SKILL.md")) return "skillFileMissing";
		if (error.includes("Selected path is not a folder")) return "invalidSkillFolder";
		if (error.includes("security_check_blocked")) return "security_check_blocked";
	}
	async getSkillListCached() {
		const now = Date.now();
		if (this.skillListCache && this.skillListCache.expiresAt > now) return this.skillListCache.results;
		if (this.skillListInFlight) return this.skillListInFlight;
		this.skillListInFlight = (async () => {
			try {
				const results = (await this.getSkillList({ global: true })).results || [];
				this.skillListCache = {
					results,
					expiresAt: Date.now() + WorkbuddyAgentAdapterNext.SKILL_LIST_CACHE_TTL_MS
				};
				return results;
			} catch (error) {
				console.warn("[WorkbuddyAdapter] getSkillListCached failed:", error);
				return [];
			} finally {
				this.skillListInFlight = null;
			}
		})();
		return this.skillListInFlight;
	}
	invalidateSkillListCache() {
		this.skillListCache = null;
	}
	extractStableSkillId(skill) {
		if (typeof skill.skillId === "string" && skill.skillId) return skill.skillId;
		if (typeof skill.slug === "string" && skill.slug) return skill.slug;
	}
	async findInstalledSkillInfoByName(skillName) {
		if (!skillName) return;
		const match = (await this.getSkillListCached()).find((skill) => skill.name === skillName);
		if (!match) return;
		return {
			filePath: match.filePath,
			skillId: this.extractStableSkillId(match),
			skillVersion: match.version
		};
	}
	async resolveSkillInfoByPath(filePath) {
		if (!filePath) return;
		const match = (await this.getSkillListCached()).find((skill) => skill.filePath === filePath);
		if (!match) return;
		return {
			skillId: this.extractStableSkillId(match),
			skillVersion: match.version
		};
	}
