	registerPoiConsentCallback(callback) {
		this.poiConsentCallbacks.add(callback);
		if (!this.poiConsentUnsubscribe && this.daemonClient) try {
			this.poiConsentUnsubscribe = this.requireWorkbuddyInternalApi().$on("connector:requirePoiConsent", (payload) => {
				const req = payload;
				if (req?.mcpServerName) this.poiConsentCallbacks.forEach((cb) => {
					try {
						cb(req);
					} catch (err) {
						console.error("[WorkbuddyAdapter] PoiConsent callback error:", err);
					}
				});
			});
		} catch {}
		return () => {
			this.poiConsentCallbacks.delete(callback);
		};
	}
