	async connectConnector(configId) {
		try {
			if (this.daemonClient?.connectorConnect) {
				const raw = await this.daemonClient.connectorConnect(configId);
				if (raw?.needsTokenConfig) {
					requestTokenConfig({
						configId,
						reason: "missing"
					});
					return { success: false };
				}
				if (!raw.success && await this.isTokenModeConnector(configId)) {
					requestTokenConfig({
						configId,
						reason: "connect-failed",
						errorMessage: raw.error
					});
					return { success: false };
				}
				return {
					success: raw.success,
					error: raw.error,
					needsAuth: raw.needsAuth,
					cancelled: raw.cancelled
				};
			}
			if (this.client.sessions.connectConnector) return await this.client.sessions.connectConnector(configId);
			return {
				success: false,
				error: "Not supported"
			};
		} catch (error) {
			console.error("[WorkbuddyAdapter] connectConnector failed:", error);
			return {
				success: false,
				error: error instanceof Error ? error.message : "Connection failed"
			};
		}
	}
